def comps(a,val=0):
    H,W=a.shape; seen=np.zeros_like(a,bool); out=[]
    for r in range(H):
        for c in range(W):
            if a[r,c]==val and not seen[r,c]:
                stack=[(r,c)]; seen[r,c]=True; cells=set()
                while stack:
                    rr,cc=stack.pop(); cells.add((rr,cc))
                    for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
                        nr,nc=rr+dr,cc+dc
                        if 0<=nr<H and 0<=nc<W and a[nr,nc]==val and not seen[nr,nc]:
                            seen[nr,nc]=True; stack.append((nr,nc))
                out.append(cells)
    return out
