import numpy as np
def f(a):
    a=np.array(a); H,W=a.shape; b=a.copy()
    def comps(val=0):
        seen=np.zeros_like(a,bool); outs=[]
        for r in range(H):
            for c in range(W):
                if a[r,c]==val and not seen[r,c]:
                    stack=[(r,c)]; seen[r,c]=True; cells=set()
                    while stack:
                        rr,cc=stack.pop(); cells.add((rr,cc))
                        for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
                            nr,nc=rr+dr,cc+dc
                            if 0<=nr<H and 0<=nc<W and a[nr,nc]==val and not seen[nr,nc]:
                                seen[nr,nc]=True; stack.append((nr,nc))
                    outs.append(cells)
        return outs
    for cells in comps():
        rs=[r for r,c in cells]; cs=[c for r,c in cells]
        hgt=max(rs)-min(rs)+1; wid=max(cs)-min(cs)+1
        if len(cells)==hgt*wid and len(cells)>=2:
            for p in cells: b[p]=7
        else:
            for p in cells: b[p]=8
    return b.tolist()
