def solve(a):
    a=np.array(a); H,W=a.shape; b=a.copy()
    seen=np.zeros_like(a,bool)
    for r in range(H):
        for c in range(W):
            if a[r,c]==0 and not seen[r,c]:
                stack=[(r,c)]; seen[r,c]=True; cells=[]
                while stack:
                    rr,cc=stack.pop(); cells.append((rr,cc))
                    for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
                        nr,nc=rr+dr,cc+dc
                        if 0<=nr<H and 0<=nc<W and a[nr,nc]==0 and not seen[nr,nc]:
                            seen[nr,nc]=True; stack.append((nr,nc))
                # enclosed if not touching border AND size>=3? check demos
                touch=any(r==0 or c==0 or r==H-1 or c==W-1 for r,c in cells)
